import{_ as t,o,c as r,a2 as n}from"./chunks/framework.CqdVOxXJ.js";const s="/rakkii-cars-guide/screenshots/08-lane-4-billing-chain-receivables-storage-credit-notes/01-who-owes-us.png",a="/rakkii-cars-guide/screenshots/08-lane-4-billing-chain-receivables-storage-credit-notes/02-credit-note.png",m=JSON.parse('{"title":"8. Lane 4 — Billing chain, receivables, storage & credit notes","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/08-lane-4-billing-chain-receivables-storage-credit-notes.md","filePath":"chapters/08-lane-4-billing-chain-receivables-storage-credit-notes.md","lastUpdated":1793268728000}'),i={name:"chapters/08-lane-4-billing-chain-receivables-storage-credit-notes.md"};function l(g,e,d,c,h,u){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="_8-lane-4-—-billing-chain-receivables-storage-credit-notes" tabindex="-1">8. Lane 4 — Billing chain, receivables, storage &amp; credit notes <a class="header-anchor" href="#_8-lane-4-—-billing-chain-receivables-storage-credit-notes" aria-label="Permalink to &quot;8. Lane 4 — Billing chain, receivables, storage &amp; credit notes&quot;">​</a></h1><p><strong>For:</strong> Shop Owner · <strong>Hubs:</strong> Workshop (Pay, Release, Overview tabs), Finance</p><p>This chapter covers what happens around the money once a car is billed: releasing with an override, chasing what customers and insurers owe, recording partial payments, charging storage for cars left behind, and correcting invoices with credit notes and refunds.</p><h2 id="_8-1-releasing-with-an-owner-override" tabindex="-1">8.1 Releasing with an Owner override <a class="header-anchor" href="#_8-1-releasing-with-an-owner-override" aria-label="Permalink to &quot;8.1 Releasing with an Owner override&quot;">​</a></h2><p>The release gates protect the shop (<a href="/rakkii-cars-guide/chapters/05-lane-1-private-walk-in-jobs#_5-10-release-checklist-gate-pass-and-acceptance">Chapter 5</a>). Sometimes the owner decides to let the car go anyway — a long-time customer paying tomorrow, or a fleet officer who forgot the signed form.</p><ol><li>Open the job&#39;s <strong>Release</strong> tab (job must be <strong>Ready for pickup</strong>).</li><li>Tick what is true among <strong>Keys logged</strong>, <strong>Documents in / out</strong>, <strong>Customer signed release</strong>.</li><li>Tick <strong>Owner override</strong> and type the <strong>Override reason</strong> (required), for example &quot;Regular customer, balance PHP 12,500 by GCash 25 Oct, approved by owner&quot;.</li><li>If invoices are not yet posted and the job holds release for invoices, fill <strong>Reason to release before invoices are posted</strong> (owner only).</li><li>Press <strong>Release car</strong>.</li></ol><p>The release record keeps <strong>Owner override: Yes · Reason: …</strong> and who released the car. Every override is also visible to the owner afterwards.</p><table tabindex="0"><thead><tr><th>What the override passes</th><th>Notes</th></tr></thead><tbody><tr><td>Customer balance not zero</td><td>The open balance goes to <strong>Who owes us</strong></td></tr><tr><td>Down payment required before release</td><td></td></tr><tr><td>Release checks not all ticked</td><td>Owner only — &quot;Only the owner can override the release checklist.&quot;</td></tr><tr><td>Hold until the insurer pays</td><td></td></tr><tr><td>Invoices not posted</td><td>Separate owner-only reason</td></tr></tbody></table><p>The override does <strong>not</strong> pass missing QC photos (use the QC override reason) or a missing LOA on an insurance job.</p><h2 id="_8-2-who-owes-us-finance-receivables" tabindex="-1">8.2 Who owes us (<code>/finance/receivables</code>) <a class="header-anchor" href="#_8-2-who-owes-us-finance-receivables" aria-label="Permalink to &quot;8.2 Who owes us (`/finance/receivables`)&quot;">​</a></h2><p>Every posted invoice with a balance appears here, for customers and insurers.</p><ul><li>Filter with <strong>All / Customers / Insurers</strong>, an age <strong>Bucket</strong>, and <strong>Insurer</strong>.</li><li>Columns: <strong>Job</strong>, <strong>Who</strong>, <strong>Insurer</strong>, <strong>Invoice</strong>, <strong>Billing</strong> (transmittal), <strong>Running days</strong>, <strong>Expected</strong> (pay date), <strong>Balance</strong>, <strong>Storage</strong>, <strong>Age</strong>, <strong>Last follow-up</strong>.</li><li>Totals: <strong>Open amount</strong>, <strong>Overdue amount</strong>, and the amount per age band (0–30, 31–60, 61–90, 90+ days by default).</li><li><strong>Running days</strong> shows each insurer&#39;s average days to pay.</li></ul><p>Age is counted from the <strong>expected pay date</strong> (invoice date + insurer days to pay, or the customer&#39;s credit terms).</p><h3 id="record-a-billing-transmittal" tabindex="-1">Record a billing transmittal <a class="header-anchor" href="#record-a-billing-transmittal" aria-label="Permalink to &quot;Record a billing transmittal&quot;">​</a></h3><p>When you send or hand over the billing packet:</p><ol><li>On the invoice row press <strong>Billing transmittal</strong>.</li><li>Fill <strong>Transmittal date</strong> (date sent), <strong>Transmittal ref</strong> (reference number), <strong>For collection</strong>, <strong>Received by</strong>, <strong>Received on</strong> and <strong>Terms (days)</strong> (payment terms).</li><li><strong>Save</strong>. The <strong>Billing</strong> column shows the transmittal.</li></ol><p>The owner sets <strong>Flag bill not transmitted after</strong> (2 days by default) so posted invoices without a transmittal are flagged.</p><h3 id="log-collection-follow-ups" tabindex="-1">Log collection follow-ups <a class="header-anchor" href="#log-collection-follow-ups" aria-label="Permalink to &quot;Log collection follow-ups&quot;">​</a></h3><ol><li>Press <strong>Log follow-up</strong> on the row.</li><li>Type the <strong>Note</strong> (&quot;Called Ms. Reyes, cheque ready 30 Oct&quot;), <strong>Save note</strong>.</li><li>The latest note and time show under <strong>Last follow-up</strong>.</li></ol><p><img src="'+s+'" alt="Who owes us with buckets, transmittal and follow-up actions"></p><h2 id="_8-3-recording-partial-payments" tabindex="-1">8.3 Recording partial payments <a class="header-anchor" href="#_8-3-recording-partial-payments" aria-label="Permalink to &quot;8.3 Recording partial payments&quot;">​</a></h2><p>Customers and insurers often pay in parts. Record each payment on the job when it arrives.</p><ol><li>Job <strong>Pay › Record a payment</strong>.</li><li><strong>Who paid</strong>: Customer or Insurer (separate payments for each share).</li><li><strong>Amount</strong>: what actually arrived. For payers with withholding, record the net amount received.</li><li><strong>Method</strong>: <strong>Cash</strong>, <strong>GCash</strong>, <strong>Maya</strong>, <strong>Bank transfer</strong>, <strong>Card</strong> or <strong>Other</strong>.</li><li>Bank transfers: <strong>Bank account</strong> (the code the customer used), <strong>Particular</strong> (often the plate), <strong>Reference</strong>.</li><li><strong>Apply to invoice</strong>: choose the invoice. <strong>Deposited to</strong>: which shop account received it.</li><li><strong>Record payment</strong>. Repeat for each instalment. <strong>Payments on this job</strong> lists them all; <strong>Print acknowledgement</strong> prints a receipt (not a BIR official receipt).</li></ol><h3 id="finance-›-payments-finance-payments" tabindex="-1">Finance › Payments (<code>/finance/payments</code>) <a class="header-anchor" href="#finance-›-payments-finance-payments" aria-label="Permalink to &quot;Finance › Payments (`/finance/payments`)&quot;">​</a></h3><ul><li><strong>Payments</strong> tab: every payment in a date range (<strong>Paid from / Paid to</strong>), method chips, <strong>Include voided</strong>, <strong>Export CSV</strong>, <strong>Print</strong>. Footer: <strong>Total collected (net of refunds)</strong>.</li><li><strong>Pending proofs</strong> tab: payment screenshots customers uploaded on the Customer Portal. Press <strong>View screenshot</strong>, check the money really arrived, then <strong>Confirm</strong> (records the payment) or <strong>Reject</strong>.</li><li>A wrong payment is <strong>Voided</strong> with a reason, never deleted.</li></ul><h2 id="_8-4-storage-fees" tabindex="-1">8.4 Storage fees <a class="header-anchor" href="#_8-4-storage-fees" aria-label="Permalink to &quot;8.4 Storage fees&quot;">​</a></h2><p>Cars left after they are ready can be charged storage.</p><p><strong>Shop setting:</strong> <strong>Free days after ready</strong> (7 by default) and <strong>Daily storage rate</strong> (blank until the owner sets it) in <strong>Admin › Shop settings › Workshop rules › Storage fees</strong>.</p><p><strong>On the job</strong> (Overview tab, <strong>Storage</strong> card; also shown read-only to technicians):</p><ul><li>The card explains: &quot;Storage starts when the job is Ready. Grace 7 days · <em>rate</em> pesos a day.&quot;</li><li>Inside grace: &quot;Ready <em>n</em> days. Inside the 7-day grace. No storage fee yet.&quot;</li><li>After grace: &quot;Ready <em>n</em> days · <em>d</em> days past the 7-day grace · <em>rate</em> pesos a day · accruing ₱…&quot;.</li></ul><p><strong>To bill it</strong></p><ol><li>Owner: press <strong>Confirm storage line</strong>. A storage fee line for the customer is added to the job.</li><li>Post (or re-post) the customer invoice; the <strong>Storage</strong> column on the invoice and in <strong>Who owes us</strong> shows the amount.</li></ol><p><strong>To forgive or change it</strong> (owner or admin)</p><ul><li><strong>Waive storage</strong> with a <strong>Waive reason</strong> — left off the invoice; reason kept.</li><li><strong>Adjust storage</strong> with <strong>Adjusted amount (pesos)</strong> and <strong>Adjust reason</strong>.</li><li>Different rules for one car: set <strong>Grace days for this job</strong> and <strong>Daily rate for this job (pesos)</strong>, <strong>Save storage for this job</strong>. Blank inherits the shop default.</li></ul><h2 id="_8-5-credit-notes-and-refunds" tabindex="-1">8.5 Credit notes and refunds <a class="header-anchor" href="#_8-5-credit-notes-and-refunds" aria-label="Permalink to &quot;8.5 Credit notes and refunds&quot;">​</a></h2><p>A posted invoice is never edited. Correct it with a <strong>credit note</strong> (lowers what the invoice bills) and, if money must go back, a <strong>refund</strong>.</p><h3 id="issue-a-credit-note" tabindex="-1">Issue a credit note <a class="header-anchor" href="#issue-a-credit-note" aria-label="Permalink to &quot;Issue a credit note&quot;">​</a></h3><ol><li><strong>Pay › Invoices</strong>, on the posted invoice press <strong>Credit</strong>.</li><li>Enter <strong>Amount (PHP, incl. VAT)</strong>, <strong>Credit note date</strong> and <strong>Reason</strong>.</li><li>Press <strong>Issue credit note</strong>. A row &quot;Credit note <em>number</em> · Against <em>invoice</em>&quot; appears; the invoice shows &quot;Credited −₱…&quot; and &quot;Bills ₱…&quot;.</li><li><strong>Print</strong> the credit note for the customer or insurer.</li></ol><p>The invoice stays posted; the payer&#39;s balance, receivables, commission basis and blanket PO usage all go down. No money moves. A sales commission already paid on that job may be flagged for review (<a href="/rakkii-cars-guide/chapters/04-sales-agent-guide#commission-statuses-sales-me-commission">Chapter 4</a>). <strong>Void credit</strong> reverses a credit note.</p><h3 id="refund-a-payment" tabindex="-1">Refund a payment <a class="header-anchor" href="#refund-a-payment" aria-label="Permalink to &quot;Refund a payment&quot;">​</a></h3><ol><li>In <strong>Payments on this job</strong>, press <strong>Refund</strong> on the payment.</li><li>Enter <strong>Amount</strong>, <strong>Method</strong>, <strong>Paid from</strong> (shop account), <strong>Refunded on</strong>, <strong>Reference</strong> and <strong>Reason</strong>.</li><li><strong>Refund</strong>. The payment shows &quot;Refunded ₱…&quot;. <strong>Void refund</strong> if entered by mistake.</li></ol><h3 id="voiding-an-invoice" tabindex="-1">Voiding an invoice <a class="header-anchor" href="#voiding-an-invoice" aria-label="Permalink to &quot;Voiding an invoice&quot;">​</a></h3><p><strong>Void</strong> on an invoice needs a reason and is blocked while credit notes or refunds exist: &quot;Void the credit notes first.&quot; / &quot;Void the refunds first.&quot;</p><p><img src="'+a+'" alt="Issue credit note dialog and the credited invoice row"></p>',44)])])}const f=t(i,[["render",l]]);export{m as __pageData,f as default};
